import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { env } from '../config/env';

/** Where uploaded files (bill photos) live. Keys are generated by the server, never by the client. */
export interface FileStorage {
  readonly name: 'local' | 's3';
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
}

const SAFE_KEY = /^[a-z0-9][a-z0-9/_.-]*$/i;
function checkKey(key: string): string {
  if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error(`Unsafe storage key: ${key}`);
  return key;
}

/** Files under UPLOAD_DIR (default ./uploads). Not served statically: only through authorised routes. */
export class LocalStorage implements FileStorage {
  readonly name = 'local' as const;
  constructor(private readonly root = path.resolve(env.UPLOAD_DIR)) {}

  private file(key: string): string {
    const full = path.resolve(this.root, checkKey(key));
    if (!full.startsWith(this.root + path.sep)) throw new Error('Storage key escapes the upload folder');
    return full;
  }
  async put(key: string, data: Buffer): Promise<void> {
    const file = this.file(key);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, data);
  }
  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.file(key));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw err;
    }
  }
  async delete(key: string): Promise<void> {
    await rm(this.file(key), { force: true });
  }
}

/** Any S3-compatible bucket (AWS S3, Cloudflare R2, MinIO). The SDK is loaded only when used. */
export class S3Storage implements FileStorage {
  readonly name = 's3' as const;
  private client: Promise<import('@aws-sdk/client-s3').S3Client> | null = null;

  private sdk() {
    return import('@aws-sdk/client-s3');
  }
  private s3() {
    this.client ??= this.sdk().then(
      ({ S3Client }) =>
        new S3Client({
          region: env.S3_REGION || 'auto',
          endpoint: env.S3_ENDPOINT || undefined,
          forcePathStyle: env.S3_FORCE_PATH_STYLE,
          credentials: env.S3_ACCESS_KEY_ID ? { accessKeyId: env.S3_ACCESS_KEY_ID, secretAccessKey: env.S3_SECRET_ACCESS_KEY } : undefined,
        }),
    );
    return this.client;
  }
  async put(key: string, data: Buffer, contentType: string): Promise<void> {
    const { PutObjectCommand } = await this.sdk();
    await (await this.s3()).send(new PutObjectCommand({ Bucket: env.S3_BUCKET, Key: checkKey(key), Body: data, ContentType: contentType }));
  }
  async get(key: string): Promise<Buffer | null> {
    const { GetObjectCommand, NoSuchKey } = await this.sdk();
    try {
      const out = await (await this.s3()).send(new GetObjectCommand({ Bucket: env.S3_BUCKET, Key: checkKey(key) }));
      return out.Body ? Buffer.from(await out.Body.transformToByteArray()) : null;
    } catch (err) {
      if (err instanceof NoSuchKey || (err as { name?: string }).name === 'NoSuchKey') return null;
      throw err;
    }
  }
  async delete(key: string): Promise<void> {
    const { DeleteObjectCommand } = await this.sdk();
    await (await this.s3()).send(new DeleteObjectCommand({ Bucket: env.S3_BUCKET, Key: checkKey(key) }));
  }
}

let storage: FileStorage | null = null;
export function getStorage(): FileStorage {
  if (!storage) {
    if (env.STORAGE_PROVIDER === 's3' && !env.S3_BUCKET) throw new Error('STORAGE_PROVIDER=s3 needs S3_BUCKET');
    storage = env.STORAGE_PROVIDER === 's3' ? new S3Storage() : new LocalStorage();
  }
  return storage;
}
/** Swap the storage (tests). */
export const setStorage = (s: FileStorage | null) => {
  storage = s;
};
